-- tatooine: city areas from the client's datatables/clientregion/tatooine.iff
-- (generated by tools/client/city_regions_sql.py). The cities' old regions stay
-- as their no-build areas.

-- bestine: centre -1204, -3692, radius 375
INSERT INTO swganh.planet_regions (region_name, region_file, x, z, width, height, planet_id, build, no_build_type)
  VALUES ('bestine', 'tatooine_region_names', -1204, -3692, 0, 750, 8, 0, 0);
UPDATE swganh.cities c JOIN swganh.planet_regions r ON c.city_region = r.region_id
  SET c.city_region = LAST_INSERT_ID()
  WHERE c.planet_id = 8 AND r.region_name = 'bestine' AND r.build != 0;

